('5-1-nokta','hunt','[{"id": "5-1-nokta-1", "prompt": "Buluşma saatini doğru gösteren cümle hangisidir?", "choices": ["Saat 09-30''da bahçedeyiz.", "Saat 09.30''da bahçedeyiz.", "Saat 09/30''da bahçedeyiz.", "Hiçbiri"], "answer": "Saat 09.30''da bahçedeyiz.", "explanation": "Saat ile dakika arasına nokta konur."}, {"id": "5-1-nokta-2", "prompt": "Sıra sayısının rakamla doğru yazımı hangisidir?", "choices": ["3. sıradaki oyuncu başladı.", "3 sıradaki oyuncu başladı.", "3, sıradaki oyuncu başladı.", "Hiçbiri"], "answer": "3. sıradaki oyuncu başladı.", "explanation": "Rakamdan sonra sıra bildiren nokta, üçüncü anlamını verir."}, {"id": "5-1-nokta-3", "prompt": "Gün, ay ve yıl rakamla yazılırken doğru biçim hangisidir?", "choices": ["14,10,2026", "14:10:2026", "14.10.2026", "Hiçbiri"], "answer": "14.10.2026", "explanation": "Nokta, rakamla gösterilen tarih bölümlerini ayırabilir."}, {"id": "5-1-nokta-4", "prompt": "Tarafsız bir haber cümlesi noktayla bitirilecekse hangi yazım doğrudur?", "choices": ["Oyunumuz birazdan başlayacak;", "Oyunumuz birazdan başlayacak.", "Oyunumuz birazdan başlayacak,", "Hiçbiri"], "answer": "Oyunumuz birazdan başlayacak.", "explanation": "Tamamlanmış haber cümlesi noktayla bitirilebilir."}, {"id": "5-1-nokta-5", "prompt": "Doktor kelimesinin noktalı kısaltması hangisidir?", "choices": ["Dr.", "D.r", "Dr,", "Hiçbiri"], "answer": "Dr.", "explanation": "Doktor kelimesinin kısaltması Dr. biçimindedir."}, {"id": "5-1-nokta-6", "prompt": "İkinci takım anlamını doğru veren biçim hangisidir?", "choices": ["2 takım", "2, takım", "2. takım", "Hiçbiri"], "answer": "2. takım", "explanation": "2. biçimi sıra, 2 takım biçimi ise iki adet takım bildirir."}, {"id": "5-1-nokta-7", "prompt": "Saat gösteriminde noktanın doğru kullanıldığı örnek hangisidir?", "choices": ["Oyun 10-15''te bitecek.", "Oyun 10.15''te bitecek.", "Oyun 10/15''te bitecek.", "Hiçbiri"], "answer": "Oyun 10.15''te bitecek.", "explanation": "Saat ve dakikayı ayıran nokta 10.15 biçiminde kullanılır."}, {"id": "5-1-nokta-8", "prompt": "Tamamlanmış duyurunun sonuna uygun işaret eklenmiş seçenek hangisidir?", "choices": ["Kartlar masanın üzerindedir.", "Kartlar masanın üzerindedir,", "Kartlar masanın üzerindedir:", "Hiçbiri"], "answer": "Kartlar masanın üzerindedir.", "explanation": "Duyuru tamamlanmış bir bilgi cümlesidir; sonuna nokta konabilir."}, {"id": "5-1-nokta-9", "prompt": "Genel ağ adresindeki doğru ayırma işareti hangi seçenektedir?", "choices": ["meb,gov,tr", "meb;gov;tr", "meb.gov.tr", "Hiçbiri"], "answer": "meb.gov.tr", "explanation": "Genel ağ adreslerinin bölümlerinde nokta kullanılır."}, {"id": "5-1-nokta-10", "prompt": "Beşinci durak anlamını veren doğru yazım hangisidir?", "choices": ["5, durak", "5. durak", "5 durak", "Hiçbiri"], "answer": "5. durak", "explanation": "Nokta, rakamdan sonra sıra sayısı anlamı oluşturur."}]'::jsonb),
