('5-3-amac','hunt','[{"id": "5-3-amac-1", "prompt": "“Arkadaşımı dinlemek için yanına oturdum.” cümlesindeki belirgin anlam ilişkisi hangisidir?", "choices": ["amaç", "gerçekleşmiş neden", "karşılaştırma", "Hiçbiri"], "answer": "amaç", "explanation": "Cümledeki ifade amaç anlamını kurar; sözün kesinlik düzeyi ve amacı buna göre değerlendirilir."}, {"id": "5-3-amac-2", "prompt": "“Sunuma hazırlanmak amacıyla not tuttum.” cümlesindeki belirgin anlam ilişkisi hangisidir?", "choices": ["gerçekleşmiş neden", "karşılaştırma", "amaç", "Hiçbiri"], "answer": "amaç", "explanation": "Cümledeki ifade amaç anlamını kurar; sözün kesinlik düzeyi ve amacı buna göre değerlendirilir."}, {"id": "5-3-amac-3", "prompt": "“Duygumu anlatabilmek için mektup yazdım.” cümlesindeki belirgin anlam ilişkisi hangisidir?", "choices": ["karşılaştırma", "amaç", "gerçekleşmiş neden", "Hiçbiri"], "answer": "amaç", "explanation": "Cümledeki ifade amaç anlamını kurar; sözün kesinlik düzeyi ve amacı buna göre değerlendirilir."}, {"id": "5-3-amac-4", "prompt": "“Sorunu çözmek üzere öğretmene danıştım.” cümlesindeki belirgin anlam ilişkisi hangisidir?", "choices": ["amaç", "gerçekleşmiş neden", "karşılaştırma", "Hiçbiri"], "answer": "amaç", "explanation": "Cümledeki ifade amaç anlamını kurar; sözün kesinlik düzeyi ve amacı buna göre değerlendirilir."}, {"id": "5-3-amac-5", "prompt": "“Arkadaşını görmek için bahçeye çıktı.” cümlesindeki belirgin anlam ilişkisi hangisidir?", "choices": ["gerçekleşmiş neden", "karşılaştırma", "amaç", "Hiçbiri"], "answer": "amaç", "explanation": "Cümledeki ifade amaç anlamını kurar; sözün kesinlik düzeyi ve amacı buna göre değerlendirilir."}, {"id": "5-3-amac-6", "prompt": "“Daha açık konuşmak amacıyla cümlesini değiştirdi.” cümlesindeki belirgin anlam ilişkisi hangisidir?", "choices": ["karşılaştırma", "amaç", "gerçekleşmiş neden", "Hiçbiri"], "answer": "amaç", "explanation": "Cümledeki ifade amaç anlamını kurar; sözün kesinlik düzeyi ve amacı buna göre değerlendirilir."}, {