('5-3-duygu','hunt','[{"id": "5-3-duygu-1", "prompt": "“Keşke dün arkadaşımın sözünü kesmeseydim.” cümlesinde belirgin duygu veya tutum hangisidir?", "choices": ["pişmanlık", "sevinç", "şaşırma", "Hiçbiri"], "answer": "pişmanlık", "explanation": "Cümlenin bağlamında pişmanlık öne çıkar; aynı kelime farklı bağlamda başka bir duygu taşıyabilir."}, {"id": "5-3-duygu-2", "prompt": "“İyi ki düşünceni benimle paylaştın.” cümlesinde belirgin duygu veya tutum hangisidir?", "choices": ["üzüntü", "şüphe", "memnuniyet", "Hiçbiri"], "answer": "memnuniyet", "explanation": "Cümlenin bağlamında memnuniyet öne çıkar; aynı kelime farklı bağlamda başka bir duygu taşıyabilir."}, {"id": "5-3-duygu-3", "prompt": "“Acaba notumu yanlış mı anladı?” cümlesinde belirgin duygu veya tutum hangisidir?", "choices": ["sevinç", "şüphe ve merak", "kesin bilgi", "Hiçbiri"], "answer": "şüphe ve merak", "explanation": "Cümlenin bağlamında şüphe ve merak öne çıkar; aynı kelime farklı bağlamda başka bir duygu taşıyabilir."}, {"id": "5-3-duygu-4", "prompt": "“Yazık ki bu buluşmaya katılamadım.” cümlesinde belirgin duygu veya tutum hangisidir?", "choices": ["üzüntü", "sevinç", "küçümseme", "Hiçbiri"], "answer": "üzüntü", "explanation": "Cümlenin bağlamında üzüntü öne çıkar; aynı kelime farklı bağlamda başka bir duygu taşıyabilir."}, {"id": "5-3-duygu-5", "prompt": "“Nasıl olmuş da bu kadar güzel bir pano hazırlamışlar!” cümlesinde belirgin duygu veya tutum hangisidir?", "choices": ["pişmanlık", "şüphe", "şaşırma", "Hiçbiri"], "answer": "şaşırma", "explanation": "Cümlenin bağlamında şaşırma öne çıkar; aynı kelime farklı bağlamda başka bir duygu taşıyabilir."}, {"id": "5-3-duygu-6", "prompt": "“Keşke yarınki gösteriyi izleyebilsem.” cümlesinde belirgin duygu veya tutum hangisidir?", "choices": ["küçümseme", "istek", "kesin bilgi", "Hiçbiri"], "answer": "istek", "explanation": "Cümlenin bağlamında istek öne çıkar; aynı kelime farklı bağlamda başka bir duygu taşıyabilir."}, {"id": "5-3-duygu-7", "prompt": "“N