('5-4-zamir','hunt','[{"id": "5-4-zamir-1", "prompt": "“Zeynep kilimi inceledi. Zeynep not aldı.” İkinci cümlede tekrarlanan kişi veya kişiler yerine hangisi kullanılabilir?", "choices": ["Biz", "O", "Onlar", "Hiçbiri"], "answer": "O", "explanation": "İkinci cümledeki adın sayı ve kişi anlamını “O” korur; gönderme önceki cümleden anlaşılır."}, {"id": "5-4-zamir-2", "prompt": "“Çocuklar sofrayı kurdu. Çocuklar konukları karşıladı.” İkinci cümlede tekrarlanan kişi veya kişiler yerine hangisi kullanılabilir?", "choices": ["Onlar", "O", "Ben", "Hiçbiri"], "answer": "Onlar", "explanation": "İkinci cümledeki adın sayı ve kişi anlamını “Onlar” korur; gönderme önceki cümleden anlaşılır."}, {"id": "5-4-zamir-3", "prompt": "“Dedem mektubu okudu. Dedem gülümsedi.” İkinci cümlede tekrarlanan kişi veya kişiler yerine hangisi kullanılabilir?", "choices": ["Onlar", "Siz", "O", "Hiçbiri"], "answer": "O", "explanation": "İkinci cümledeki adın sayı ve kişi anlamını “O” korur; gönderme önceki cümleden anlaşılır."}, {"id": "5-4-zamir-4", "prompt": "“Komşular bahçeyi temizledi. Komşular dinlendi.” İkinci cümlede tekrarlanan kişi veya kişiler yerine hangisi kullanılabilir?", "choices": ["Sen", "Onlar", "O", "Hiçbiri"], "answer": "Onlar", "explanation": "İkinci cümledeki adın sayı ve kişi anlamını “Onlar” korur; gönderme önceki cümleden anlaşılır."}, {"id": "5-4-zamir-5", "prompt": "“Ece masalı dinledi. Ece bir soru sordu.” İkinci cümlede tekrarlanan kişi veya kişiler yerine hangisi kullanılabilir?", "choices": ["O", "Onlar", "Biz", "Hiçbiri"], "answer": "O", "explanation": "İkinci cümledeki adın sayı ve kişi anlamını “O” korur; gönderme önceki cümleden anlaşılır."}, {"id": "5-4-zamir-6", "prompt": "“Konuklar sergiyi gezdi. Konuklar teşekkür etti.” İkinci cümlede tekrarlanan kişi veya kişiler yerine hangisi kullanılabilir?", "choices": ["Ben", "O", "Onlar", "Hiçbiri"], "answer": "Onlar", "explanation": "İkinci cümledeki adın sayı ve kişi anlamını “Onlar” korur; gönderme önceki cümleden an