('5-5-yeniden-kurma','hunt','[{"id": "5-5-yeniden-kurma-1", "prompt": "“Duru duyuruyu arkadaşları daha iyi anlasın diye yeniden yazdı.” cümlesi anlamı korunarak hangi biçimde yeniden kurulabilir?", "choices": ["Duru, duyuruyu hiç kimse okumasın diye sakladı.", "Duru, arkadaşları anladığı için duyuruyu sildi.", "Duru, duyuruyu daha anlaşılır kılmak için tekrar yazdı.", "Hiçbiri"], "answer": "Duru, duyuruyu daha anlaşılır kılmak için tekrar yazdı.", "explanation": "Doğru seçenekte kişiler, olay sırası ve amaç/neden korunur; diğer seçenekler temel bilgiyi değiştirir."}, {"id": "5-5-yeniden-kurma-2", "prompt": "“Toplantıdan önce herkes sorusunu hazırladı.” cümlesi anlamı korunarak hangi biçimde yeniden kurulabilir?", "choices": ["Toplantıda hiç soru hazırlanmadı.", "Herkes, toplantı başlamadan sorusunu belirledi.", "Herkes sorusunu toplantı bittikten sonra hazırladı.", "Hiçbiri"], "answer": "Herkes, toplantı başlamadan sorusunu belirledi.", "explanation": "Doğru seçenekte kişiler, olay sırası ve amaç/neden korunur; diğer seçenekler temel bilgiyi değiştirir."}, {"id": "5-5-yeniden-kurma-3", "prompt": "“Elif arkadaşının sözünü bitirmesini bekledi.” cümlesi anlamı korunarak hangi biçimde yeniden kurulabilir?", "choices": ["Elif, arkadaşı konuşmasını tamamlayınca söz aldı.", "Elif, arkadaşı bitirmeden sözünü kesti.", "Elif, arkadaşının hiç konuşmamasını istedi.", "Hiçbiri"], "answer": "Elif, arkadaşı konuşmasını tamamlayınca söz aldı.", "explanation": "Doğru seçenekte kişiler, olay sırası ve amaç/neden korunur; diğer seçenekler temel bilgiyi değiştirir."}, {"id": "5-5-yeniden-kurma-4", "prompt": "“Saat değiştiği için duyuru güncellendi.” cümlesi anlamı korunarak hangi biçimde yeniden kurulabilir?", "choices": ["Saat aynı kaldığı için duyuru kaldırıldı.", "Duyurunun değişmesi saati geri aldı.", "Duyuru, değişen saate göre yeniden düzenlendi.", "Hiçbiri"], "answer": "Duyuru, değişen saate göre yeniden düzenlendi.", "explanation": "Doğru seçenekte kişiler, olay sırası ve amaç/neden korunur; diğer seçenekler temel bilgiyi değiştirir."}, {"id": "5-5-yeniden-kurma-5", "prompt": "“Mert fikrini bir örnekle açıkladı.” cümlesi anlamı korunarak hangi biçimde yeniden kurulabilir?", "choices": ["Mert, hiçbir örnek vermeden konuştu.", "Mert, düşüncesini anlatırken örnek kullandı.", "Mert, fikrini söylemekten vazgeçti.", "Hiçbiri"], "answer": "Mert, düşüncesini anlatırken örnek kullandı.", "explanation": "Doğru seçenekte kişiler, olay sırası ve amaç/neden korunur; diğer seçenekler temel bilgiyi değiştirir."}, {"id": "5-5-yeniden-kurma-6", "prompt": "“Herkesin katılabileceği bir zaman seçildi.” cümlesi anlamı korunarak hangi biçimde yeniden kurulabilir?", "choices": ["Buluşma için herkesin uygun olduğu zaman belirlendi.", "Yalnızca bir kişinin katılacağı zaman seçildi.", "Hiç kimsenin uygun olmadığı zaman belirlendi.", "Hiçbiri"], "answer": "Buluşma için herkesin uygun olduğu zaman belirlendi.", "explanation": "Doğru seçenekte kişiler, olay sırası ve amaç/neden korunur; diğer seçenekler temel bilgiyi değiştirir."}, {"id": "5-5-yeniden-kurma-7", "prompt": "“Öğrenciler metni okuduktan sonra özetledi.” cümlesi anlamı korunarak hangi biçimde yeniden kurulabilir?", "choices": ["Öğrenciler metni okumadan özetledi.", "Öğrenciler özeti okuduktan sonra metni yazdı.", "Öğrenciler önce metni okudu, ardından özetini çıkardı.", "Hiçbiri"], "answer": "Öğrenciler önce metni okudu, ardından özetini çıkardı.", "explanation": "Doğru seçenekte kişiler, olay sırası ve amaç/neden korunur; diğer seçenekler temel bilgiyi değiştirir."}, {"id": "5-5-yeniden-kurma-8", "prompt": "“Yanlış bilgi yayılmasın diye eski not kaldırıldı.” cümlesi anlamı korunarak hangi biçimde yeniden kurulabilir?", "choices": ["Eski not doğru olduğu için hemen dağıtıldı.", "Eski not, yanlış bilginin yayılmasını önlemek için alındı.", "Eski not, yanlış bilgi yayılsın diye çoğaltıldı.", "Hiçbiri"], "answer": "Eski not, yanlış bilginin yayılmasını önlemek için alındı.", "explanation": "Doğru seçenekte kişiler, olay sırası ve amaç/neden korunur; diğer seçenekler temel bilgiyi değiştirir."}, {"id": "5-5-yeniden-kurma-9", "prompt": "“Arkadaşım yardım istediğinde onu dinledim.” cümlesi anlamı korunarak hangi biçimde yeniden kurulabilir?", "choices": ["Yardım talep eden arkadaşıma kulak verdim.", "Arkadaşım yardım isteyince onu susturdum.", "Yardım istemeyen arkadaşımdan uzaklaştım.", "Hiçbiri"], "answer": "Yardım talep eden arkadaşıma kulak verdim.", "explanation": "Doğru seçenekte kişiler, olay sırası ve amaç/neden korunur; diğer seçenekler temel bilgiyi değiştirir."}, {"id": "5-5-yeniden-kurma-10", "prompt": "“Grup kararı birlikte değerlendirerek verdi.” cümlesi anlamı korunarak hangi biçimde yeniden kurulabilir?", "choices": ["Kararı gruptan habersiz biri tek başına verdi.", "Grup hiçbir değerlendirme yapmadan dağıldı.", "Grup, karara ortak bir değerlendirmeyle ulaştı.", "Hiçbiri"], "answer": "Grup, karara ortak bir değerlendirmeyle ulaştı.", "explanation": "Doğru seçenekte kişiler, olay sırası ve amaç/neden korunur; diğer seçenekler temel bilgiyi değiştirir."}]'::jsonb),
